const EmotesManager = require("./EmotesManager")
const Validator = require("./Validator")

class Dimension {
    constructor(coordinates) {
        this.dimension = coordinates
    }

    isInside(pos) {
        const { x, z } = pos
        const { x1, x2, z1, z2 } = this.dimension

        return x > x1
            && x < x2
            && z > z1
            && z < z2
    }
}

class DanceFloor {
    #users = new Map()
    #danceLoops = new Map()
    #validator = new Validator()
    #dimension
    #emotesManager
    #playerApi

    constructor(coordinates, emotesManager, playerApi) {
        const { x1, x2, z1, z2 } = coordinates

        Object.entries(coordinates).forEach(([key, coordinate]) => {
            this.#validator
                .required(coordinate, key)
                .nonNegative(coordinate, key)
        })

        if (x1 >= x2) throw new Error("x1 must be less than x2")
        if (z1 >= z2) throw new Error("z1 must be less than z2")

        this.#dimension = new Dimension(coordinates)
        this.#emotesManager = emotesManager
        this.#playerApi = playerApi
    }

    async addUser(user, position) {
        if (this.#users.has(user.id)) return { success: false, reason: "already_added" }
        if (!this.#dimension.isInside(position)) return { success: false, reason: "outside_floor" }

        this.#users.set(user.id, user)
        this.#startRandomDancing(user)
        return { success: true }
    }

    removeUser(userId) {
        const removed = this.#users.delete(userId)
        if (removed) this.#stopDancing(userId)
        return removed
    }

    isInside(pos) {
        return this.#dimension.isInside(pos)
    }

    hasUser(userId) {
        return this.#users.has(userId)
    }

    getUsers() {
        return [...this.#users.values()]
    }

    #startRandomDancing(user) {
        const dance = async () => {
            if (!this.#users.has(user.id)) return

            const emote = this.#randomEmote()
            if (!emote) return

            const durationMs = (emote.duration ?? 1) * 1000
            if (!Number.isFinite(durationMs) || durationMs <= 0) return

            const result = await this.#playerApi.emote(emote.id, user.id)
            if (result?.hasError?.()) {
                this.#stopDancing(user.id)
                return
            }

            if (!this.#users.has(user.id)) return

            const timeoutId = setTimeout(dance, durationMs)
            this.#danceLoops.set(user.id, timeoutId)
        }

        dance().catch(() => { })
    }

    #stopDancing(userId) {
        const timeoutId = this.#danceLoops.get(userId)
        if (timeoutId) clearTimeout(timeoutId)

        this.#danceLoops.delete(userId)
    }

    #randomEmote() {
        const all = this.#emotesManager.getAll()
        if (!all.length) return null
        return all[Math.floor(Math.random() * all.length)]
    }

    destroy() {
        for (const userId of this.#users.keys()) {
            this.#stopDancing(userId)
        }
        this.#users.clear()
    }
}

class DanceFloorsManager {
    #floors = new Map()
    #userToFloor = new Map()
    #emotesManager = new EmotesManager()
    #playerApi

    constructor(playerApi) {
        this.#playerApi = playerApi
    }

    create(floorName, coordinate) {
        if (this.#floors.has(floorName)) return false

        this.#floors.set(floorName, new DanceFloor(coordinate, this.#emotesManager, this.#playerApi))
        return true
    }

    remove(floorName) {
        const floor = this.#floors.get(floorName)
        if (!floor) return false

        for (const userId of floor.getUsers().map(u => u.id)) {
            this.#userToFloor.delete(userId)
        }

        floor.destroy()
        return this.#floors.delete(floorName)
    }

    get(floorName) {
        return this.#floors.get(floorName) ?? null
    }

    getAll() {
        return [...this.#floors.keys()]
    }

    async handleMovement(user, position) {
        if (!position) return

        const currentFloorName = this.#userToFloor.get(user.id)
        if (currentFloorName) {
            const currentFloor = this.#floors.get(currentFloorName)
            if (currentFloor && currentFloor.isInside(position)) {
                return
            }

            
            if (currentFloor) {
                currentFloor.removeUser(user.id)
                this.#userToFloor.delete(user.id)
            }
        }

        for (const [floorName, floor] of this.#floors) {
            if (floor.isInside(position)) {
                const result = await floor.addUser(user, position)
                if (result.success) {
                    this.#userToFloor.set(user.id, floorName)
                }
                return
            }
        }
    }

    destroy() {
        for (const floor of this.#floors.values()) {
            floor.destroy()
        }
        
        this.#floors.clear()
        this.#userToFloor.clear()
    }
}

module.exports = DanceFloorsManager